use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut sorted_values = Vec::new();
    for (key, value) in input.as_array().unwrap() {
        sorted_values.push(serde_json::Value::Number(value as i64));
    }
    sorted_values.sort_unstable_by(|a, b| {
        if a.as_i64() == b.as_i64() {
            a.as_str().cmp(b.as_str())
        } else {
            a.as_i64().cmp(b.as_i64())
        }
    });
    serde_json::Value::Array(sorted_values)
}
